112	static void do_consume(amqp_connection_state_t conn, amqp_bytes_t queue,
113	                       int no_ack, int count, int prefetch_count,
114	                       const char *const *argv) {
115	  int i;
116	
117	  /* If there is a limit, set the qos to match */
118	  if (count > 0 && count <= AMQP_CONSUME_MAX_PREFETCH_COUNT &&
119	      !amqp_basic_qos(conn, 1, 0, count, 0)) {
120	    die_rpc(amqp_get_rpc_reply(conn), "basic.qos");
121	  }
122	
123	  /* if there is a maximum number of messages to be received at a time, set the
124	   * qos to match */
125	  if (prefetch_count > 0 && prefetch_count <= AMQP_CONSUME_MAX_PREFETCH_COUNT) {
126	    /* the maximum number of messages to be received at a time must be less
127	     * than the global maximum number of messages. */
128	    if (!(count > 0 && count <= AMQP_CONSUME_MAX_PREFETCH_COUNT &&
129	          prefetch_count >= count)) {
130	      if (!amqp_basic_qos(conn, 1, 0, prefetch_count, 0)) {
131	        die_rpc(amqp_get_rpc_reply(conn), "basic.qos");
132	      }
133	    }
134	  }
