236:     return AMQP_STATUS_SOCKET_CLOSED;
237:   }
238:   switch (res) {
239:     case AMQP_PRIVATE_STATUS_SOCKET_NEEDREAD:
240:       res = amqp_poll(fd, AMQP_SF_POLLIN, deadline);
241:       break;
242:     case AMQP_PRIVATE_STATUS_SOCKET_NEEDWRITE:
243:       res = amqp_poll(fd, AMQP_SF_POLLOUT, deadline);
244:       break;
245:   }
246:   return res;
