249: ssize_t amqp_try_send(amqp_connection_state_t state, const void *buf,
250:                       size_t len, amqp_time_t deadline, int flags) {
251:   ssize_t res;
252:   void *buf_left = (void *)buf;
253:   /* Assume that len is not going to be larger than ssize_t can hold. */
254:   ssize_t len_left = (size_t)len;
255: 
256: start_send:
257:   res = amqp_socket_send(state->socket, buf_left, len_left, flags);
258: 
259:   if (res > 0) {
260:     len_left -= res;
261:     buf_left = (char *)buf_left + res;
262:     if (0 == len_left) {
263:       return (ssize_t)len;
264:     }
265:     goto start_send;
266:   }
267:   res = do_poll(state, res, deadline);
268:   if (AMQP_STATUS_OK == res) {
269:     goto start_send;
270:   }
271:   if (AMQP_STATUS_TIMEOUT == res) {
272:     return (ssize_t)len - len_left;
273:   }
274:   return res;
275: }
