292: static int connect_socket(struct addrinfo *addr, amqp_time_t deadline) {
293:   int one = 1;
294:   u_long nonblocking = 1;
295:   SOCKET sockfd;
296:   int last_error;
297: 
298:   /*
299:    * This cast is to squash warnings on Win64, see:
300:    * http://stackoverflow.com/questions/1953639/is-it-safe-to-cast-socket-to-int-under-win64
301:    */
302: 
303:   sockfd = (int)socket(addr->ai_family, addr->ai_socktype, addr->ai_protocol);
304:   if (INVALID_SOCKET == sockfd) {
305:     return AMQP_STATUS_SOCKET_ERROR;
306:   }
307: 
308:   /* Set the socket to be non-blocking */
309:   if (SOCKET_ERROR == ioctlsocket(sockfd, FIONBIO, &nonblocking)) {
310:     last_error = AMQP_STATUS_SOCKET_ERROR;
311:     goto err;
312:   }
313: 
314:   /* Disable nagle */
315:   if (SOCKET_ERROR == setsockopt(sockfd, IPPROTO_TCP, TCP_NODELAY,
316:                                  (const char *)&one, sizeof(one))) {
317:     last_error = AMQP_STATUS_SOCKET_ERROR;
318:     goto err;
319:   }
320: 
321:   /* Enable TCP keepalives */
322:   if (SOCKET_ERROR == setsockopt(sockfd, SOL_SOCKET, SO_KEEPALIVE,
323:                                  (const char *)&one, sizeof(one))) {
324:     last_error = AMQP_STATUS_SOCKET_ERROR;
325:     goto err;
326:   }
327: 
328:   if (SOCKET_ERROR != connect(sockfd, addr->ai_addr, (int)addr->ai_addrlen)) {
329:     return (int)sockfd;
330:   }
331: 
332:   if (WSAEWOULDBLOCK != WSAGetLastError()) {
333:     last_error = AMQP_STATUS_SOCKET_ERROR;
334:     goto err;
335:   }
336: 
337:   last_error =
338:       amqp_poll((int)sockfd, AMQP_SF_POLLOUT | AMQP_SF_POLLERR, deadline);
339:   if (AMQP_STATUS_OK != last_error) {
340:     goto err;
341:   }
342: 
343:   {
344:     int result;
345:     int result_len = sizeof(result);
346: 
347:     if (SOCKET_ERROR == getsockopt(sockfd, SOL_SOCKET, SO_ERROR,
348:                                    (char *)&result, &result_len) ||
349:         result != 0) {
350:       last_error = AMQP_STATUS_SOCKET_ERROR;
351:       goto err;
352:     }
353:   }
354: 
355:   return (int)sockfd;
356: 
357: err:
358:   closesocket(sockfd);
359:   return last_error;
360: }
361: #else
362: static int connect_socket(struct addrinfo *addr, amqp_time_t deadline) {
363:   int one = 1;
364:   int sockfd;
365:   int flags;
366:   int last_error;
367: 
368:   sockfd = socket(addr->ai_family, addr->ai_socktype, addr->ai_protocol);
369:   if (-1 == sockfd) {
370:     return AMQP_STATUS_SOCKET_ERROR;
371:   }
372: 
373:   /* Enable CLOEXEC on socket */
374:   flags = fcntl(sockfd, F_GETFD);
375:   if (flags == -1 || fcntl(sockfd, F_SETFD, (long)(flags | FD_CLOEXEC)) == -1) {
376:     last_error = AMQP_STATUS_SOCKET_ERROR;
377:     goto err;
378:   }
379: 
380:   /* Set the socket as non-blocking */
381:   flags = fcntl(sockfd, F_GETFL);
382:   if (flags == -1 || fcntl(sockfd, F_SETFL, (long)(flags | O_NONBLOCK)) == -1) {
383:     last_error = AMQP_STATUS_SOCKET_ERROR;
384:     goto err;
385:   }
386: 
387: #ifdef SO_NOSIGPIPE
388:   /* Turn off SIGPIPE on platforms that support it, BSD, MacOSX */
389:   if (0 != setsockopt(sockfd, SOL_SOCKET, SO_NOSIGPIPE, &one, sizeof(one))) {
390:     last_error = AMQP_STATUS_SOCKET_ERROR;
391:     goto err;
392:   }
393: #endif /* SO_NOSIGPIPE */
394: 
395:   /* Disable nagle */
396:   if (0 != setsockopt(sockfd, IPPROTO_TCP, TCP_NODELAY, &one, sizeof(one))) {
397:     last_error = AMQP_STATUS_SOCKET_ERROR;
398:     goto err;
399:   }
400: 
401:   /* Enable TCP keepalives */
402:   if (0 != setsockopt(sockfd, SOL_SOCKET, SO_KEEPALIVE, &one, sizeof(one))) {
403:     last_error = AMQP_STATUS_SOCKET_ERROR;
404:     goto err;
405:   }
406: 
407:   if (0 == connect(sockfd, addr->ai_addr, addr->ai_addrlen)) {
408:     return sockfd;
409:   }
410: 
411:   if (EINPROGRESS != errno) {
412:     last_error = AMQP_STATUS_SOCKET_ERROR;
413:     goto err;
414:   }
415: 
416:   last_error = amqp_poll(sockfd, AMQP_SF_POLLOUT, deadline);
417:   if (AMQP_STATUS_OK != last_error) {
418:     goto err;
419:   }
420: 
421:   {
422:     int result;
423:     socklen_t result_len = sizeof(result);
424: 
425:     if (-1 == getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &result, &result_len) ||
426:         result != 0) {
427:       last_error = AMQP_STATUS_SOCKET_ERROR;
428:       goto err;
429:     }
430:   }
431: 
432:   return sockfd;
433: 
434: err:
435:   close(sockfd);
436:   return last_error;
437: }
438: #endif
