440: int amqp_open_socket_inner(char const *hostname, int portnumber,
441:                            amqp_time_t deadline) {
442:   struct addrinfo hint;
443:   struct addrinfo *address_list;
444:   struct addrinfo *addr;
445:   char portnumber_string[33];
446:   int sockfd = -1;
447:   int last_error;
448: 
449:   last_error = amqp_os_socket_init();
450:   if (AMQP_STATUS_OK != last_error) {
451:     return last_error;
452:   }
453: 
454:   memset(&hint, 0, sizeof(hint));
455:   hint.ai_family = PF_UNSPEC; /* PF_INET or PF_INET6 */
456:   hint.ai_socktype = SOCK_STREAM;
457:   hint.ai_protocol = IPPROTO_TCP;
458: 
459:   (void)sprintf(portnumber_string, "%d", portnumber);
460: 
461:   last_error = getaddrinfo(hostname, portnumber_string, &hint, &address_list);
462:   if (0 != last_error) {
463:     return AMQP_STATUS_HOSTNAME_RESOLUTION_FAILED;
464:   }
465: 
466:   for (addr = address_list; addr; addr = addr->ai_next) {
467:     sockfd = connect_socket(addr, deadline);
468: 
469:     if (sockfd >= 0) {
470:       last_error = AMQP_STATUS_OK;
471:       break;
472:     } else if (sockfd == AMQP_STATUS_TIMEOUT) {
473:       last_error = sockfd;
474:       break;
475:     }
476:   }
477: 
478:   freeaddrinfo(address_list);
479:   if (last_error != AMQP_STATUS_OK || sockfd == -1) {
480:     return last_error;
481:   }
482:   return sockfd;
483: }
