622: /*
623:  * Check to see if we have data in our buffer. If this returns 1, we
624:  * will avoid an immediate blocking read in amqp_simple_wait_frame.
625:  */
626: amqp_boolean_t amqp_data_in_buffer(amqp_connection_state_t state) {
627:   return (state->sock_inbound_offset < state->sock_inbound_limit);
