630: static int consume_one_frame(amqp_connection_state_t state,
631:                              amqp_frame_t *decoded_frame) {
632:   int res;
633: 
634:   amqp_bytes_t buffer;
635:   buffer.len = state->sock_inbound_limit - state->sock_inbound_offset;
636:   buffer.bytes =
637:       ((char *)state->sock_inbound_buffer.bytes) + state->sock_inbound_offset;
638: 
639:   res = amqp_handle_input(state, buffer, decoded_frame);
640:   if (res < 0) {
641:     return res;
642:   }
643: 
644:   state->sock_inbound_offset += res;
645: 
646:   return AMQP_STATUS_OK;
647: }
