649: static int recv_with_timeout(amqp_connection_state_t state,
650:                              amqp_time_t timeout) {
651:   ssize_t res;
652:   int fd;
653: 
654: start_recv:
655:   res = amqp_socket_recv(state->socket, state->sock_inbound_buffer.bytes,
656:                          state->sock_inbound_buffer.len, 0);
657: 
658:   if (res < 0) {
659:     fd = amqp_get_sockfd(state);
660:     if (-1 == fd) {
661:       return AMQP_STATUS_CONNECTION_CLOSED;
662:     }
663:     switch (res) {
664:       default:
665:         return (int)res;
666:       case AMQP_PRIVATE_STATUS_SOCKET_NEEDREAD:
667:         res = amqp_poll(fd, AMQP_SF_POLLIN, timeout);
668:         break;
669:       case AMQP_PRIVATE_STATUS_SOCKET_NEEDWRITE:
670:         res = amqp_poll(fd, AMQP_SF_POLLOUT, timeout);
671:         break;
672:     }
673:     if (AMQP_STATUS_OK == res) {
674:       goto start_recv;
675:     }
676:     return (int)res;
677:   }
678: 
679:   state->sock_inbound_limit = res;
680:   state->sock_inbound_offset = 0;
681: 
682:   res = amqp_time_s_from_now(&state->next_recv_heartbeat,
683:                              amqp_heartbeat_recv(state));
684:   if (AMQP_STATUS_OK != res) {
685:     return (int)res;
686:   }
687:   return AMQP_STATUS_OK;
688: }
689: 
690: int amqp_try_recv(amqp_connection_state_t state) {
691:   amqp_time_t timeout;
692:   int res;
693: 
694:   while (amqp_data_in_buffer(state)) {
695:     amqp_frame_t frame;
696:     res = consume_one_frame(state, &frame);
697: 
698:     if (AMQP_STATUS_OK != res) {
699:       return res;
700:     }
701: 
702:     if (frame.frame_type != 0) {
703:       amqp_pool_t *channel_pool;
704:       amqp_frame_t *frame_copy;
705:       amqp_link_t *link;
706: 
707:       channel_pool = amqp_get_or_create_channel_pool(state, frame.channel);
708:       if (NULL == channel_pool) {
709:         return AMQP_STATUS_NO_MEMORY;
710:       }
711: 
712:       frame_copy = amqp_pool_alloc(channel_pool, sizeof(amqp_frame_t));
713:       link = amqp_pool_alloc(channel_pool, sizeof(amqp_link_t));
714: 
715:       if (frame_copy == NULL || link == NULL) {
716:         return AMQP_STATUS_NO_MEMORY;
717:       }
718: 
719:       *frame_copy = frame;
720: 
721:       link->next = NULL;
722:       link->data = frame_copy;
723: 
724:       if (state->last_queued_frame == NULL) {
725:         state->first_queued_frame = link;
726:       } else {
727:         state->last_queued_frame->next = link;
728:       }
729:       state->last_queued_frame = link;
730:     }
731:   }
732:   res = amqp_time_from_now(&timeout, &(struct timeval){0});
733:   if (AMQP_STATUS_OK != res) {
734:     return res;
735:   }
736: 
737:   return recv_with_timeout(state, timeout);
738: }
739: 
740: static int wait_frame_inner(amqp_connection_state_t state,
741:                             amqp_frame_t *decoded_frame,
742:                             amqp_time_t timeout_deadline) {
743:   amqp_time_t deadline;
744:   int res;
745: 
746:   for (;;) {
747:     while (amqp_data_in_buffer(state)) {
748:       res = consume_one_frame(state, decoded_frame);
749: 
750:       if (AMQP_STATUS_OK != res) {
751:         return res;
752:       }
753: 
754:       if (AMQP_FRAME_HEARTBEAT == decoded_frame->frame_type) {
755:         amqp_maybe_release_buffers_on_channel(state, 0);
756:         continue;
757:       }
758: 
759:       if (decoded_frame->frame_type != 0) {
760:         /* Complete frame was read. Return it. */
761:         return AMQP_STATUS_OK;
762:       }
763:     }
764: 
765:   beginrecv:
766:     res = amqp_time_has_past(state->next_send_heartbeat);
767:     if (AMQP_STATUS_TIMER_FAILURE == res) {
768:       return res;
769:     } else if (AMQP_STATUS_TIMEOUT == res) {
770:       amqp_frame_t heartbeat;
771:       heartbeat.channel = 0;
772:       heartbeat.frame_type = AMQP_FRAME_HEARTBEAT;
773: 
774:       res = amqp_send_frame(state, &heartbeat);
775:       if (AMQP_STATUS_OK != res) {
776:         return res;
777:       }
778:     }
779:     deadline = amqp_time_first(timeout_deadline,
780:                                amqp_time_first(state->next_recv_heartbeat,
781:                                                state->next_send_heartbeat));
782: 
783:     /* TODO this needs to wait for a _frame_ and not anything written from the
784:      * socket */
785:     res = recv_with_timeout(state, deadline);
786: 
787:     if (AMQP_STATUS_TIMEOUT == res) {
788:       if (amqp_time_equal(deadline, state->next_recv_heartbeat)) {
789:         amqp_socket_close(state->socket, AMQP_SC_FORCE);
790:         return AMQP_STATUS_HEARTBEAT_TIMEOUT;
791:       } else if (amqp_time_equal(deadline, timeout_deadline)) {
792:         return AMQP_STATUS_TIMEOUT;
793:       } else if (amqp_time_equal(deadline, state->next_send_heartbeat)) {
794:         /* send heartbeat happens before we do recv_with_timeout */
795:         goto beginrecv;
796:       } else {
797:         amqp_abort("Internal error: unable to determine timeout reason");
798:       }
799:     } else if (AMQP_STATUS_OK != res) {
800:       return res;
801:     }
802:   }
803: }
