848: int amqp_put_back_frame(amqp_connection_state_t state, amqp_frame_t *frame) {
849:   amqp_link_t *link = amqp_create_link_for_frame(state, frame);
850:   if (NULL == link) {
851:     return AMQP_STATUS_NO_MEMORY;
852:   }
853: 
854:   if (NULL == state->first_queued_frame) {
855:     state->first_queued_frame = link;
856:     state->last_queued_frame = link;
857:     link->next = NULL;
858:   } else {
859:     link->next = state->first_queued_frame;
860:     state->first_queued_frame = link;
861:   }
862: 
863:   return AMQP_STATUS_OK;
864: }
