866: int amqp_simple_wait_frame_on_channel(amqp_connection_state_t state,
867:                                       amqp_channel_t channel,
868:                                       amqp_frame_t *decoded_frame) {
869:   amqp_frame_t *frame_ptr;
870:   amqp_link_t *cur;
871:   int res;
872: 
873:   for (cur = state->first_queued_frame; NULL != cur; cur = cur->next) {
874:     frame_ptr = cur->data;
875: 
876:     if (channel == frame_ptr->channel) {
877:       state->first_queued_frame = cur->next;
878:       if (NULL == state->first_queued_frame) {
879:         state->last_queued_frame = NULL;
880:       }
881: 
882:       *decoded_frame = *frame_ptr;
883: 
884:       return AMQP_STATUS_OK;
885:     }
886:   }
887: 
888:   for (;;) {
889:     res = wait_frame_inner(state, decoded_frame, amqp_time_infinite());
890: 
891:     if (AMQP_STATUS_OK != res) {
892:       return res;
893:     }
894: 
895:     if (channel == decoded_frame->channel) {
896:       return AMQP_STATUS_OK;
897:     } else {
898:       res = amqp_queue_frame(state, decoded_frame);
899:       if (res != AMQP_STATUS_OK) {
900:         return res;
901:       }
902:     }
903:   }
904: }
