934: static int amqp_simple_wait_method_list(amqp_connection_state_t state,
935:                                         amqp_channel_t expected_channel,
936:                                         amqp_method_number_t *expected_methods,
937:                                         amqp_time_t deadline,
938:                                         amqp_method_t *output) {
939:   amqp_frame_t frame;
940:   struct timeval tv;
941:   struct timeval *tvp;
942: 
943:   int res = amqp_time_tv_until(deadline, &tv, &tvp);
944:   if (res != AMQP_STATUS_OK) {
945:     return res;
946:   }
947: 
948:   res = amqp_simple_wait_frame_noblock(state, &frame, tvp);
949:   if (AMQP_STATUS_OK != res) {
950:     return res;
951:   }
952: 
953:   if (AMQP_FRAME_METHOD != frame.frame_type ||
954:       expected_channel != frame.channel ||
955:       !amqp_id_in_reply_list(frame.payload.method.id, expected_methods)) {
956:     return AMQP_STATUS_WRONG_METHOD;
957:   }
958:   *output = frame.payload.method;
959:   return AMQP_STATUS_OK;
960: }
