1142: /*
1143:  * Merge base and add tables. If the two tables contain an entry with the same
1144:  * key, the entry from the add table takes precedence. For entries that are both
1145:  * tables with the same key, the table is recursively merged.
1146:  */
1147: int amqp_merge_capabilities(const amqp_table_t *base, const amqp_table_t *add,
1148:                             amqp_table_t *result, amqp_pool_t *pool) {
1149:   int i;
1150:   int res;
1151:   amqp_pool_t temp_pool;
1152:   amqp_table_t temp_result;
1153:   assert(base != NULL);
1154:   assert(result != NULL);
1155:   assert(pool != NULL);
1156: 
1157:   if (NULL == add) {
1158:     return amqp_table_clone(base, result, pool);
1159:   }
1160: 
1161:   init_amqp_pool(&temp_pool, 4096);
1162:   temp_result.num_entries = 0;
1163:   temp_result.entries =
1164:       amqp_pool_alloc(&temp_pool, sizeof(amqp_table_entry_t) *
1165:                                       (base->num_entries + add->num_entries));
1166:   if (NULL == temp_result.entries) {
1167:     res = AMQP_STATUS_NO_MEMORY;
1168:     goto error_out;
1169:   }
1170:   for (i = 0; i < base->num_entries; ++i) {
1171:     temp_result.entries[temp_result.num_entries] = base->entries[i];
1172:     temp_result.num_entries++;
1173:   }
1174:   for (i = 0; i < add->num_entries; ++i) {
1175:     amqp_table_entry_t *e =
1176:         amqp_table_get_entry_by_key(&temp_result, add->entries[i].key);
1177:     if (NULL != e) {
1178:       if (AMQP_FIELD_KIND_TABLE == add->entries[i].value.kind &&
1179:           AMQP_FIELD_KIND_TABLE == e->value.kind) {
1180:         amqp_table_entry_t *be =
1181:             amqp_table_get_entry_by_key(base, add->entries[i].key);
1182: 
1183:         res = amqp_merge_capabilities(&be->value.value.table,
1184:                                       &add->entries[i].value.value.table,
1185:                                       &e->value.value.table, &temp_pool);
1186:         if (AMQP_STATUS_OK != res) {
1187:           goto error_out;
1188:         }
1189:       } else {
1190:         e->value = add->entries[i].value;
1191:       }
1192:     } else {
1193:       temp_result.entries[temp_result.num_entries] = add->entries[i];
1194:       temp_result.num_entries++;
1195:     }
1196:   }
1197:   res = amqp_table_clone(&temp_result, result, pool);
1198: error_out:
1199:   empty_amqp_pool(&temp_pool);
1200:   return res;
1201: }
