30: static char *make_command_line(const char *const *argv) {
31:   int i;
32:   size_t len = 1; /* initial quotes */
33:   char *buf;
34:   char *dest;
35: 
36:   /* calculate the length of the required buffer, making worst
37:      case assumptions for simplicity */
38:   for (i = 0;;) {
39:     /* each character could need escaping */
40:     len += strlen(argv[i]) * 2;
41: 
42:     if (!argv[++i]) {
43:       break;
44:     }
45: 
46:     len += 3; /* quotes, space, quotes */
47:   }
48: 
49:   len += 2; /* final quotes and the terminating zero */
50: 
51:   dest = buf = malloc(len);
52:   if (!buf) {
53:     die("allocating memory for subprocess command line");
54:   }
55: 
56:   /* Here we perform the inverse of the CommandLineToArgvW
57:      function.  Note that its rules are slightly crazy: A
58:      sequence of backslashes only act to escape if followed by
59:      double quotes.  A sequence of backslashes not followed by
60:      double quotes is untouched. */
61: 
62:   for (i = 0;;) {
63:     const char *src = argv[i];
64:     int backslashes = 0;
65: 
66:     *dest++ = '\"';
67: 
68:     for (;;) {
69:       switch (*src) {
70:         case 0:
71:           goto done;
72: 
73:         case '\"':
74:           for (; backslashes; backslashes--) {
75:             *dest++ = '\\';
76:           }
77: 
78:           *dest++ = '\\';
79:           *dest++ = '\"';
80:           break;
81: 
82:         case '\\':
83:           backslashes++;
84:           *dest++ = '\\';
85:           break;
86: 
87:         default:
88:           backslashes = 0;
89:           *dest++ = *src;
90:           break;
91:       }
92: 
93:       src++;
94:     }
95:   done:
96:     for (; backslashes; backslashes--) {
97:       *dest++ = '\\';
98:     }
99: 
100:     *dest++ = '\"';
101: 
102:     if (!argv[++i]) {
103:       break;
104:     }
105: 
106:     *dest++ = ' ';
107:   }
108: 
109:   *dest++ = 0;
110:   return buf;
111: }
